from part1 import D, B
B['w4']={'name':'Week 4 · Libraries','drills':[
 D('Seeded dice','M5',['random','seed','import'],'Write roll(sides, seed=None) returning a random int from 1 to sides inclusive. When seed is given, call random.seed(seed) first so results repeat. Import what you need at the top.','import random\n\ndef roll(sides, seed=None):\n    pass\n','assert roll(6,seed=7)==roll(6,seed=7)\nassert all(1<=roll(6) <=6 for _ in range(200))\nassert {roll(2) for _ in range(100)}=={1,2}','import random\n\ndef roll(sides, seed=None):\n    if seed is not None: random.seed(seed)\n    return random.randint(1,sides)\n',['random.randint(1, sides) includes both ends.','if seed is not None: random.seed(seed)']),
 D('Pick a winner','M5',['random.choice','random.sample','import'],'Write draw(names, k=1, seed=None): return k DISTINCT names chosen at random as a list. Same seed means same result. Raise ValueError if k is more than the number of names.','import random\n\ndef draw(names, k=1, seed=None):\n    pass\n','assert draw(list("abcde"),3,seed=1)==draw(list("abcde"),3,seed=1)\nassert len(set(draw(list("abcde"),5)))==5\ntry:\n    draw(["a"],2); assert False\nexcept ValueError: pass','import random\n\ndef draw(names, k=1, seed=None):\n    if k>len(names): raise ValueError("k too large")\n    if seed is not None: random.seed(seed)\n    return random.sample(list(names),k)\n',['random.sample picks without repeats.','Check k against len(names) first.']),
 D('FIX THE BUG: shuffling in place','M5',['random.shuffle','mutation','debugging'],'shuffled(items) should return a NEW shuffled list and leave the input alone. It returns None instead. Fix it without changing what it promises.','import random\n\ndef shuffled(items):\n    return random.shuffle(items)\n','a=[1,2,3,4,5]\nr=shuffled(a)\nassert a==[1,2,3,4,5],"input mutated"\nassert sorted(r)==[1,2,3,4,5]','import random\n\ndef shuffled(items):\n    items=list(items)\n    random.shuffle(items)\n    return items\n',['random.shuffle changes the list and returns None.','Copy first: items = list(items)'],'fix'),
 D('Weighted pick','M5',['random.choices','weights','seed'],'Write weighted_pick(options, weights, seed=None): return ONE option chosen at random, where weights says how likely each is. Seed first when a seed is given.','import random\n\ndef weighted_pick(options, weights, seed=None):\n    pass\n','assert all(weighted_pick(["a","b"],[100,0],seed=s)=="a" for s in range(25))\nassert weighted_pick(["a","b","c"],[0,0,7])=="c"\nassert weighted_pick(list("abc"),[1,1,1],seed=4)==weighted_pick(list("abc"),[1,1,1],seed=4)','import random\n\ndef weighted_pick(options, weights, seed=None):\n    if seed is not None:\n        random.seed(seed)\n    return random.choices(options, weights=weights, k=1)[0]\n',['random.choices returns a LIST, even when k is 1.','random.choices(options, weights=weights, k=1)[0]']),
 D('Summary stats','M5',['statistics','import','dict'],'Write summarize(nums) returning {"mean": ..., "median": ..., "n": ...}. Use the statistics module. Mean and median rounded to 2 places. Empty input raises ValueError.','import statistics\n\ndef summarize(nums):\n    pass\n','assert summarize([1,2,3,10])=={"mean":4.0,"median":2.5,"n":4}\ntry:\n    summarize([]); assert False\nexcept ValueError: pass','import statistics\n\ndef summarize(nums):\n    if not nums: raise ValueError("empty")\n    return {"mean":round(statistics.mean(nums),2),"median":round(statistics.median(nums),2),"n":len(nums)}\n',['statistics.mean and statistics.median.','round(x, 2)']),
 D('Command-line args','M4',['sys.argv','sys.exit','slicing'],'Write parse_args(argv): argv is a list like ["prog.py", "3", "x"]. Return the list of args after the program name. If there are none, raise SystemExit with the message "usage: prog N". (Takes argv as a parameter so it is testable.)','import sys\n\ndef parse_args(argv):\n    pass\n','assert parse_args(["p","3","x"])==["3","x"]\ntry:\n    parse_args(["p"]); assert False\nexcept SystemExit as e: assert "usage" in str(e)','import sys\n\ndef parse_args(argv):\n    a=argv[1:]\n    if not a: raise SystemExit("usage: prog N")\n    return a\n',['argv[1:] slices off the program name.','raise SystemExit("usage: prog N")']),
 D('Read an API response','M5',['dict/list nesting','raise ValueError','slicing'],'An API returns a dict like {"data": [{"title": ...}, ...]}. Write titles(response, limit=3): the first limit titles as a list. If the response has an "error" key, raise ValueError with its message.','def titles(response, limit=3):\n    pass\n','r={"data":[{"title":"Sunrise","id":1},{"title":"Harbor","id":2},{"title":"Orchard","id":3},{"title":"Meadow","id":4}]}\nassert titles(r)==["Sunrise","Harbor","Orchard"]\nassert titles(r,limit=1)==["Sunrise"] and titles({"data":[]})==[]\ntry:\n    titles({"error":"bad request"}); assert False,"should raise"\nexcept ValueError as e:\n    assert "bad" in str(e)','def titles(response, limit=3):\n    if "error" in response:\n        raise ValueError(response["error"])\n    return [item["title"] for item in response["data"]][:limit]\n',['Check for "error" before touching response["data"].','A list comprehension, then [:limit] slices it.']),
 D('Safe fetch','M5',['try/except','specific exceptions','composition'],'safe_titles(fetch, query): fetch(query) returns (status, payload). If status is not 200, or fetch raises ConnectionError, return []. Otherwise return titles(payload). Catch only ConnectionError.','def safe_titles(fetch, query):\n    pass\n','ok=lambda q:(200,{"data":[{"title":q+"1"},{"title":q+"2"}]})\nbad=lambda q:(500,{"error":"down"})\ndef boom(q): raise ConnectionError("offline")\nassert safe_titles(ok,"x")==["x1","x2"]\nassert safe_titles(bad,"x")==[] and safe_titles(boom,"x")==[]\ndef broken(q): raise KeyError("oops")\ntry:\n    safe_titles(broken,"x"); assert False,"too broad: KeyError was swallowed"\nexcept KeyError:\n    pass','def safe_titles(fetch, query):\n    try:\n        status, payload = fetch(query)\n    except ConnectionError:\n        return []\n    if status != 200:\n        return []\n    return titles(payload)\n',['Unpack the tuple: status, payload = fetch(query).','Only the fetch call goes inside the try block.']),
 D('Dice CLI (capstone)','M5',['composition','sys.argv','random','statistics'],'Write dice_report(argv, seed=0): argv is ["prog", SIDES, COUNT]. Seed ONCE before rolling, roll that many dice, and return summarize() of the results. Bad or missing numbers raise SystemExit with a usage message. Reuse parse_args and summarize.','def dice_report(argv, seed=0):\n    pass\n','r=dice_report(["p","6","50"],seed=3)\nassert r["n"]==50 and 1<=r["mean"]<=6\nassert dice_report(["p","6","50"],seed=3)==r\nfor bad in (["p"],["p","x","5"],["p","6","y"]):\n    try:\n        dice_report(bad); assert False\n    except SystemExit: pass','import random\n\ndef dice_report(argv, seed=0):\n    a=parse_args(argv)\n    try:\n        sides,count=int(a[0]),int(a[1])\n    except (ValueError,IndexError):\n        raise SystemExit("usage: prog SIDES COUNT")\n    random.seed(seed)\n    return summarize([random.randint(1,sides) for _ in range(count)])\n',['Convert with int, catch ValueError and exit.','random.seed(seed) once, then random.randint in a loop.']),
]}
B['w5']={'name':'Week 5 · Unit Tests','drills':[
 D('Write the assert','M2',['assert','testing'],'A function square(n) is already loaded for you in the check. Write run_checks() that returns True if square(3)==9, square(-2)==4 and square(0)==0, and False otherwise. Use assert inside try/except AssertionError.','def run_checks():\n    pass\n','def square(n): return n*n\nassert run_checks() is True\ndef square(n): return n+n\nassert run_checks() is False','def run_checks():\n    try:\n        assert square(3)==9\n        assert square(-2)==4\n        assert square(0)==0\n    except AssertionError:\n        return False\n    return True\n',['assert condition raises AssertionError when false.','Catch it and return False; return True at the end.']),
 D('Test a clean function','M2',['assert','edge cases'],'Write check_clean_name() that raises AssertionError (use assert) if clean_name from Week 0 mishandles: normal input, extra spaces, all caps, or the empty string (clean_name("") must be ""). Return True if all pass.','def check_clean_name():\n    pass\n','assert check_clean_name() is True','def check_clean_name():\n    assert clean_name("ada lovelace")=="Ada Lovelace"\n    assert clean_name("  ada  ")=="Ada"\n    assert clean_name("ADA")=="Ada"\n    assert clean_name("")==""\n    return True\n',['One assert per case.','Edge cases are the point: empty, spaces, case.']),
 D('FIX THE BUG: test that cannot fail','M2',['assert','testing','debugging'],'is_even_ok() is meant to verify is_even, but it can never fail: assert on a non-empty tuple is always true. Fix it so it really fails when is_even is wrong.','def is_even_ok():\n    assert (is_even(4)==True, "4 should be even")\n    assert (is_even(7)==False, "7 should be odd")\n    return True\n','assert is_even_ok() is True\n_old=is_even\nis_even=lambda n: True\ntry:\n    is_even_ok(); assert False,"test passed on broken code"\nexcept AssertionError as e:\n    assert "test passed" not in str(e)\nfinally:\n    is_even=_old','def is_even_ok():\n    assert is_even(4)==True, "4 should be even"\n    assert is_even(7)==False, "7 should be odd"\n    return True\n',['assert (cond, msg) tests the tuple, not the condition.','Write: assert cond, msg'],'fix'),
 D('Table-driven tests','M3',['loop','tuples','testing'],'Write run_table(fn, cases) where cases is a list of (input, expected). Return a list of the cases that FAILED as (input, expected, got), in order. A function that raises counts as failed with got set to the exception class name.','def run_table(fn, cases):\n    pass\n','assert run_table(abs,[(-1,1),(2,2)])==[]\nassert run_table(abs,[(-1,2)])==[(-1,2,1)]\nassert run_table(int,[("x",0)])==[("x",0,"ValueError")]','def run_table(fn, cases):\n    failed=[]\n    for inp,exp in cases:\n        try:\n            got=fn(inp)\n        except Exception as e:\n            got=type(e).__name__\n        if got!=exp: failed.append((inp,exp,got))\n    return failed\n',['Loop over cases; call fn(inp) inside try/except.','Append (inp, expected, got) when got != expected.']),
 D('Test your own grader (capstone)','M3',['composition','testing','edge cases'],'Use run_table to test grade() from Week 1. Write audit_grade() returning the failed cases for these boundary inputs: 100->A, 90->A, 89->B, 80->B, 79->C, 70->C, 69->F, 0->F. Your earlier grade() is correct, so this should return an empty list.','def audit_grade():\n    pass\n','assert audit_grade()==[]','def audit_grade():\n    cases=[(100,"A"),(90,"A"),(89,"B"),(80,"B"),(79,"C"),(70,"C"),(69,"F"),(0,"F")]\n    return run_table(grade,cases)\n',['Build the cases list, call run_table(grade, cases).','Boundaries are where off-by-one bugs live.']),
]}
